$string['check:budgethistory'] = 'Budget history';
$string['check:budgethistory:complete'] = 'This site can account for the whole of its AI use: nothing has been discarded since the plugin began keeping track. The oldest usage stored is from {$a}.';
$string['check:budgethistory:missing'] = 'A budget looks back {$a->days} days further than this site can account for. Nothing before {$a->from} can be counted.';
$string['check:budgethistory:missing_details'] = 'Budgets are added up from the usage this site still holds. Usage from before the date above is not part of that total - it was either discarded under an earlier retention setting, or predates the point from which this site has been keeping track - and it cannot be brought back. The figure the budget is measured against is therefore smaller than the spending really was, and a limit that should have been reached reads as a limit with room left. It corrects itself as those days pass out of the budget period. Until then, read the figures as a lower bound, or count the budget over a shorter period so that it covers only days this site can account for.';
$string['check:budgethistory:nobudget'] = 'No enabled rule sets a budget, so no history has to reach back anywhere.';
$string['check:budgethistory:noneyet'] = 'Nothing has been recorded yet and nothing has been discarded, so no budget is missing anything.';
$string['check:budgethistory:ok'] = 'Every budget on this site counts a period the site can account for in full. Nothing before {$a} can be counted.';
$string['check:budgetrates'] = 'Rates for budget conditions';
$string['check:budgetrates:nobudget'] = 'No enabled rule routes by budget, so nothing here depends on the rates.';
$string['check:budgetrates:noprovider'] = 'A budget in money names {$a->providers}, which has no rates entered, so it cannot be measured. {$a->rules} enabled rule(s) carry such a budget.';
$string['check:budgetrates:noprovider_details'] = 'A budget in money is counted at one provider, in the currency that provider bills in, and the currency comes from the provider\'s rates. Until a rate is entered for the provider the budget names, the budget has no currency to be in and nothing to measure, so a condition on it is satisfied neither way round and the rules carrying it never match. Enter the provider\'s rates on the rates page.';
$string['check:budgetrates:norequests'] = 'Nothing has been recorded in the last week, so there is nothing to price.';
$string['check:budgetrates:ok'] = 'A rate covered {$a->costed} of the last {$a->total} requests ({$a->percent}%), so budget conditions have something to measure.';
$string['check:budgetrates:othercurrency'] = '{$a->calls} recorded call(s) at {$a->providers} are in a currency other than the one the provider\'s rates are in now, so a budget cannot weigh them.';
$string['check:budgetrates:othercurrency_details'] = 'Money is weighed in the currency of the provider\'s rates, and a call recorded in another currency is left out as unknown rather than converted. This happens when a correction of the provider\'s currency could not reach every call, for instance one that ended while the correction was running. Saving any rate of the provider again, with its currency as it is, works every recorded call out again at the rates now in force.';
$string['check:budgetrates:uncosted'] = 'A rate covered only {$a->costed} of the last {$a->total} requests ({$a->percent}%).';
$string['check:budgetrates:uncosted_details'] = 'Spending is added up from the cost recorded on each request, and a request whose model has no rate entered has no cost at all. Budget conditions therefore see less than the site is really spending, so a limit is reached later than it should be, or never. Enter rates for the models being used - and for a provider that costs nothing, such as a model you run yourself, enter a rate of 0 rather than leaving it out. No rate means the cost is unknown; zero means it is free.';
$string['check:budgetrates:unpriced'] = 'None of the last {$a->total} requests had a rate, so there is nothing to measure a budget against.';
$string['check:budgetrates:unpriced_details'] = 'Spending is worked out from the rates entered for this site. With no rates it cannot be worked out at all, and a budget condition that cannot be measured is satisfied neither way round: neither "is under" nor "has reached". The {$a} enabled rules routing by budget can therefore never match, and requests fall through to whatever comes after them. Enter a rate for each model being used. If everything here runs on a provider that costs nothing, such as a model you run yourself, enter a rate of 0 for it: that makes the spending a known zero instead of unknown, and budgets start working again.';
$string['check:byokeligibility'] = 'How people qualify to bring a key';
$string['check:byokeligibility:noconditions'] = 'Who may bring a key is not decided by any condition, so there is nothing here to depend on.';
$string['check:byokeligibility:ok'] = 'Qualifying to bring a key does not rest on anything people can set about themselves.';
$string['check:byokeligibility:selfdeclared'] = 'People can qualify to bring a key by filling in their own profile.';
$string['check:byokeligibility:selfdeclared_details'] = 'The policy admits somebody when {$a}. That field is one the person it describes can put a value into, either on their own profile or on the registration form, so the condition asks them whether they qualify and they answer. This is right for something meant as a declaration, such as agreeing to pay for your own use, and wrong for something meant as a fact about them, such as being staff. For the second kind, use a cohort, or a field only an administrator can change: clear its "Who is this field visible to" setting, or lock it and keep it off the registration form.';
$string['check:byokkeys'] = 'Keys brought by users and courses';
$string['check:byokkeys:nokeys'] = 'Nobody has brought a key, so there is nothing to read.';
$string['check:byokkeys:ok'] = 'All {$a} brought keys can be read.';
$string['check:byokkeys:unreadable'] = '{$a->unreadable} of {$a->total} brought keys cannot be read.';
$string['check:byokkeys:unreadable_details'] = 'Keys are encrypted with a file that lives outside the database, under the site data directory. A site restored from a database backup without that file keeps every key and can read none of them. If a copy of the file still exists, restoring it recovers the keys; otherwise the only way forward is for their owners to register them again.';
$string['check:declinereach'] = 'What happens when the AI Router says no';
$string['check:declinereach:alone'] = 'Nothing is tried after the AI Router, so a request it turns down stops there.';
$string['check:declinereach:bypassable'] = '{$a} provider instance(s) after the AI Router would answer a request it turned down.';
$string['check:declinereach:details'] = 'Moodle tries providers in the site order until one of them succeeds, and a refusal looks to it like a provider that could not help. These instances are tried next, on the site\'s own key: {$a}.';
$string['check:declinereach:strict'] = '{$a} provider instance(s) come after the AI Router, and the router is set to make its refusals final.';
$string['check:managedboundary'] = 'Actions placed under the AI Router';
$string['check:managedboundary:details'] = 'This site routes {$a->actions} through the AI Router, but Moodle is building its AI manager from {$a->manager}. Requests go wherever the provider order sends them, so rules, budgets and keys people have brought are not applied and nothing else reports this. Two plugins cannot both replace the AI manager: keep one of them, or turn off the actions placed under the router here so that the site is doing what it appears to be doing.';
$string['check:managedboundary:none'] = 'No action is placed under the AI Router, so Moodle picks providers in the usual site order.';
$string['check:managedboundary:off'] = 'Routing through the AI Router is switched off, so requests are going to AI providers in the site order. The actions placed under the router are remembered and take effect again when it is switched back on.';
$string['check:managedboundary:ok'] = 'Requests for {$a} reach the AI Router whatever the provider order says.';
$string['check:managedboundary:replaced'] = 'Another plugin has taken over the AI manager, so actions placed under the AI Router no longer reach it.';
$string['check:managedboundary:unreachable'] = 'No enabled AI Router instance can carry {$a}, so requests for it are refused rather than sent to another provider.';
$string['check:norouter'] = 'The AI Router is not set up on this site yet: there are no rules and no default delegation target, so there is nothing to check.';
$string['check:notaprovider'] = 'The AI Router is not registered as an AI provider on this site, so there is no provider order, and no provider settings, for this check to be about. What the router does is decided by its own rules and settings.';
$string['check:ordernotused'] = 'Every action the AI Router carries has been placed under it, so the provider order no longer decides any of them.';
$string['check:orderpartial'] = 'This applies to the actions that still go through the provider order: {$a}. The others have been placed under the router and reach it whatever the order says.';
$string['check:recordgaps'] = 'Record gaps';
$string['check:recordgaps:gaps'] = 'The record of requests and attempts has holes in it.';
$string['check:recordgaps:gaps_details'] = '{$a->failed} write(s) failed and were let go of so that the request could go on; {$a->lost} attempt(s) and {$a->lostrequests} request(s) in the last 30 days were given up as lost because nothing recorded how they came out; {$a->stale} request(s) or attempt(s) have been open for longer than any call takes and will be given up on the next run. A bill from a provider may not match the reports by these.';
$string['check:recordgaps:ok'] = 'Every request and attempt has been recorded from beginning to end.';
