$string['eligibility:access'] = 'Who may bring their own key';
$string['eligibility:access:conditions'] = 'Only people who match the conditions below';
$string['eligibility:access:everybody'] = 'Anybody with an account';
$string['eligibility:access:nobody'] = 'Nobody';
$string['eligibility:access_help'] = 'This is checked when somebody registers a key and again on every request that would use one, so tightening it stops the keys it no longer allows from being used. Those keys are not deleted: they simply stop being used, and remain their owners\' to remove. Keys registered for a course are not governed by this, since they belong to the course rather than to whoever entered them.';
$string['eligibility:cohort'] = 'Belongs to one of these cohorts';
$string['eligibility:cohort:described'] = 'they belong to one of these cohorts: {$a}';
$string['eligibility:cohort:gone'] = 'a cohort that no longer exists ({$a})';
$string['eligibility:cohort_help'] = 'The most direct way to answer this: whoever is in the list may bring a key. Keeping a cohort up to date is something that can be handed to somebody else, or fed from an enrolment source, which is not true of roles or profile fields. Nobody matches until at least one cohort is chosen.';
$string['eligibility:heading'] = 'Who may bring their own key';
$string['eligibility:intro'] = 'A key somebody brings pays for their own requests instead of the site paying. Deciding who may do that is a policy rather than a permission, because it is asked again every time a key is used.';
$string['eligibility:match'] = 'How the conditions are combined';
